#!/usr/bin/env bash
# Reference solution, applied only by `astrona test` (the `testing:` block).
# `astrona run` never runs this. Taken from solution.md - if one changes,
# change the other.
set -euo pipefail

in_runner() { kubectl -n dac exec -i deploy/dac-runner -- sh -s; }
in_runner <<'GRADE'
set -u
. /opt/dac/grader-lib.sh
repo_change "Port the team overview dashboard to Go" "mkdir -p dashboards/go/team-overview-go && printf '%s' '' | base64 -d > dashboards/go/team-overview-go/main.go"
dac-run sh -c 'percli dac build -f dashboards/go/team-overview-go/main.go -ojson && percli apply -f built/dashboards/go/team-overview-go/main_output.json'
GRADE
